tyle="max-height:58vh;overflow:auto"><?php foreach($holidays as $holiday):?><div class="list-group-item d-flex gap-3"><span class="badge bg-danger-subtle text-danger align-self-start"><?= date('d M',strtotime($holiday['date'])) ?></span><span class="small"><?= esc($holiday['event_title']) ?></span></div><?php endforeach;?></div></div></div></div>
