<div class="modal fade" id="dayModal" tabindex="-1"><div class="modal-dialog modal-sm modal-dialog-centered"><div class="modal-content border-0 rounded-4"><div class="modal-header"><h5 class="modal-title fw-bold">Ubah Tanggal</h5><button class="btn-close" type="button" data-bs-dismiss="modal"></button></div><div class="modal-body p-4"><input type="hidden" id="dayDate"><div class="mb-3"><label class="form-label">Tipe hari</label><select class="form-select" id="dayType"><?php foreach($eventTypes as $type):?><option value="<?= esc($type['code']) ?>"><?= esc($type['name']) ?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Keterangan</label><input class="form-control" id="dayEvent"></div><div class="d-grid gap-2"><button class="btn btn-primary" id="saveDay">Simpan Perubahan</button><button class="btn btn-outline-secondary" id="resetDay">Kembalikan ke Generator</button></div></div></div></div></div>
<script>
const calId=<?= (int)$calendar['id'] ?>,csrfName='<?= csrf_token() ?>',csrfValue='<?= csrf_hash() ?>';
function fillForm(form,data){Object.entries(data).forEach(([k,v])=>{const el=form.elements.namedItem(k);if(el&&v!==null)el.value=v})}
document.querySelectorAll('.btn-edit-rule').forEach(b=>b.onclick=()=>{const d=JSON.parse(b.dataset.rule),f=document.getElementById('ruleForm');f.action='<?= base_url('academic-calendar/'.$calendar['id'].'/rules') ?>/'+d.id+'/update';fillForm(f,d);bootstrap.Modal.getOrCreateInstance(document.getElementById('ruleModal')).show()});
document.querySelectorAll('.btn-edit-event').forEach(b=>b.onclick=()=>{const d=JSON.parse(b.dataset.event),f=document.getElementById('eventForm');f.action='<?= base_url('academic-calendar/'.$calendar['id'].'/events') ?>/'+d.id+'/update';fillForm(f,d);bootstrap.Modal.getOrCreateInstance(document.getElementById('eventModal')).show()});
document.querySelectorAll('[data-bs-target="#ruleModal"][data-mode="create"]').forEach(b=>b.onclick=()=>{const f=document.getElementById('ruleForm');f.reset();f.action='<?= base_url('academic-calendar/'.$calendar['id'].'/rules/store') ?>'});document.querySelectorAll('[data-bs-target="#eventModal"][data-mode="create"]').forEach(b=>b.onclick=()=>{const f=document.getElementById('eventForm');f.reset();f.action='<?= base_url('academic-calendar/'.$calendar['id'].'/events/store') ?>'});
let currentDay=null;document.querySelectorAll('.calendar-cell[data-day]').forEach(c=>c.onclick=()=>{currentDay=JSON.parse(c.dataset.day);document.getElementById('dayDate').value=currentDay.date;document.getElementById('dayType').value=currentDay.type_code;document.getElementById('dayEvent').value=currentDay.event_title||'';document.getElementById('resetDay').disabled=!currentDay.is_manual_override;bootstrap.Modal.getOrCreateInstance(document.getElementById('dayModal')).show()});
async function dayRequest(path,extra={}){const body=new FormData();body.append(csrfName,csrfValue);body.append('date',document.getElementById('dayDate').value);Object.entries(extra).forEach(([k,v])=>body.append(k,v));const res=await fetch('<?= base_url('academic-calendar') ?>/'+calId+'/'+path,{method:'POST',body,headers:{'X-Requested-With':'XMLHttpRequest'}});const data=await res.json();if(!res.ok||!data.success)throw new Error(data.message||'Gagal menyimpan.');location.reload()}
document.getElementById('saveDay')?.addEventListener('click',()=>dayRequest('update-day',{day_type_code:document.getElementById('dayType').value,event_title:document.getElementById('dayEvent').value}).catch(e=>alert(e.message)));document.getElementById('resetDay')?.addEventListener('click',()=>dayRequest('reset-day').catch(e=>alert(e.message)));
</script>
<?php endif; ?>
<?= $this->endSection() ?>
